3	namespace App\Filament\Resources\CostEntries\Pages;
4	
5	use App\Enums\DocumentType;
6	use App\Enums\Organization;
7	use App\Filament\Resources\CostEntries\CostEntryResource;
8	use App\Models\CostEntry;
9	use Carbon\Carbon;
10	use DateTimeInterface;
11	use Filament\Actions\Action;
12	use Filament\Forms\Components\FileUpload;
13	use Filament\Notifications\Notification;
14	use Filament\Resources\Pages\ListRecords;
15	use Filament\Support\Icons\Heroicon;
16	use Illuminate\Support\Facades\Storage;
17	use OpenSpout\Reader\XLSX\Reader;
18	
19	class ListCostEntries extends ListRecords
20	{
21	    protected static string $resource = CostEntryResource::class;
22	
23	    protected function getHeaderActions(): array
24	    {
25	        return [
26	            Action::make('importExcel')
27	                ->label('Importa Excel')
28	                ->icon(Heroicon::ArrowUpTray)
29	                ->color('primary')
30	                ->modalHeading('Importa fatture da file Excel')
31	                ->modalDescription('Carica un file .xlsx con le colonne: Cedente/Prestatore, ID SDI, N° doc., Tipo documento, Data documento, Importo.')
32	                ->modalSubmitActionLabel('Importa')
33	                ->schema([
34	                    FileUpload::make('file')
35	                        ->label('File Excel (.xlsx)')
36	                        ->acceptedFileTypes([
37	                            'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
38	                            'application/vnd.ms-excel',
39	                        ])
40	                        ->disk('local')
41	                        ->directory('imports')
42	                        ->visibility('private')
43	                        ->required(),
44	                ])
45	                ->action(function (array $data): void {
46	                    $relativePath = $data['file'];
47	                    $absolutePath = Storage::disk('local')->path($relativePath);
48	
49	                    $imported = 0;
50	                    $skipped = 0;
51	
52	                    $reader = new Reader();
53	                    $reader->open($absolutePath);
54	
55	                    try {
56	                        foreach ($reader->getSheetIterator() as $sheet) {
57	                            $rowIndex = 0;
58	                            foreach ($sheet->getRowIterator() as $row) {
59	                                $rowIndex++;
60	
61	                                if ($rowIndex === 1) {
62	                                    continue;
63	                                }
64	
65	                                $cells = $row->getCells();
66	                                if (count($cells) < 6) {
67	                                    $skipped++;
68	                                    continue;
69	                                }
70	
71	                                $supplier = trim((string) $cells[0]->getValue());
72	                                if ($supplier === '') {
73	                                    $skipped++;
74	                                    continue;
75	                                }
76	
77	                                [$category, $organization] = self::parseDestination(
78	                                    isset($cells[6]) ? (string) $cells[6]->getValue() : ''
79	                                );
80	
81	                                $amount = self::parseAmount($cells[5]->getValue());
82	
83	                                $records = [];
84	
85	                                if ($organization === 'RETE') {
86	                                    $orgs = [Organization::CO, Organization::PO, Organization::SU];
87	                                    $amountCents = (int) round($amount * 100);
88	                                    $base = intdiv($amountCents, 3);
89	                                    $remainder = $amountCents % 3;
90	
91	                                    foreach ($orgs as $i => $org) {
92	                                        $records[] = [
93	                                            'supplier' => $supplier,
94	                                            'sdi_id' => trim((string) $cells[1]->getValue()) ?: null,
95	                                            'document_number' => trim((string) $cells[2]->getValue()) ?: null,
96	                                            'document_type' => DocumentType::tryFrom(trim((string) $cells[3]->getValue())),
97	                                            'document_date' => self::parseDate($cells[4]->getValue()),
98	                                            'amount' => ($base + ($i === 2 ? $remainder : 0)) / 100,
99	                                            'expense_category' => $category,
100	                                            'organization' => $org,
101	                                        ];
102	                                    }
103	                                } else {
104	                                    $records[] = [
105	                                        'supplier' => $supplier,
106	                                        'sdi_id' => trim((string) $cells[1]->getValue()) ?: null,
107	                                        'document_number' => trim((string) $cells[2]->getValue()) ?: null,
108	                                        'document_type' => DocumentType::tryFrom(trim((string) $cells[3]->getValue())),
109	                                        'document_date' => self::parseDate($cells[4]->getValue()),
110	                                        'amount' => $amount,
111	                                        'expense_category' => $category,
112	                                        'organization' => $organization !== null ? Organization::tryFrom($organization) : null,
113	                                    ];
114	                                }
115	
116	                                foreach ($records as $record) {
117	                                    CostEntry::create($record);
118	                                    $imported++;
119	                                }
120	                            }
121	                            break;
122	                        }
123	                    } finally {
124	                        $reader->close();
125	                        Storage::disk('local')->delete($relativePath);
126	                    }
127	
128	                    Notification::make()
129	                        ->title('Import completato')
130	                        ->body("Righe importate: {$imported}" . ($skipped > 0 ? " · saltate: {$skipped}" : ''))
131	                        ->success()
132	                        ->send();
133	                }),
134	            // CreateAction::make(),
135	        ];
136	    }
137	
138	    private static function parseDate(mixed $value): ?string
139	    {
140	        if ($value instanceof DateTimeInterface) {
141	            return $value->format('Y-m-d');
142	        }
143	
144	        $value = trim((string) $value);
145	        if ($value === '') {
146	            return null;
147	        }
148	
149	        foreach (['d/m/Y', 'Y-m-d', 'd-m-Y', 'd/m/y'] as $format) {
150	            $parsed = Carbon::createFromFormat($format, $value);
151	            if ($parsed !== false) {
152	                return $parsed->format('Y-m-d');
153	            }
154	        }
155	
156	        return null;
157	    }
158	
159	    private const KNOWN_ORGANIZATIONS = ['CO', 'PO', 'SU', 'RETE'];
160	
161	    /**
162	     * Splits "ALIMENTARI CO" into ['ALIMENTARI', 'CO'].
163	     * Trailing token matched against {@see self::KNOWN_ORGANIZATIONS}; everything before = expense category.
164	     *
165	     * @return array{0: ?string, 1: ?string}
166	     */
167	    private static function parseDestination(string $value): array
168	    {
169	        $value = trim($value);
170	        if ($value === '') {
171	            return [null, null];
172	        }
173	
174	        foreach (self::KNOWN_ORGANIZATIONS as $org) {
175	            $pattern = '/^(.*?)\s+' . preg_quote($org, '/') . '$/i';
176	            if (preg_match($pattern, $value, $matches) === 1) {
177	                $category = trim($matches[1]);
178	                return [$category !== '' ? $category : null, $org];
179	            }
180	        }
181	
182	        return [$value, null];
183	    }
184	
185	    private static function parseAmount(mixed $value): float
186	    {
187	        if (is_numeric($value)) {
188	            return (float) $value;
189	        }
190	
191	        $normalized = str_replace([' ', '.', ','], ['', '', '.'], (string) $value);
192	
193	        return is_numeric($normalized) ? (float) $normalized : 0.0;
194	    }
195	}
